raw_text:
{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가.적절한(부적절한)소화제",
      "start":  "p2:L15",
      "end":    "p2:L17"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나.화학물질로부터 생기는 특정 유해성",
      "start":  "p2:L19",
      "end":    "p2:L22"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다.화재진압시 착용할 보호구 및 예방조치",
      "start":  "p2:L23",
      "end":    "p2:L23"
    }
  ],
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw":  "대형 화재시",
      "reason":     "코드없음",
      "statements": [
        {
          "value": "일반적인 소화약제 및 미세 물분무를 사용하시오"
        , "line": "p2:L18"
        }
      ]
    , "suggested_code": "S5_FIREFIGHT"
    , "line": "p2:L18"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw":  "열분해 생성물",
      "reason":     "코드없음",
      "statements": [
        {
          "key": "열분해 생성물"
        , "value": "질소산화물"
        , "line": "p2:L20"
        }
      ]
    , "suggested_code": "S5_SPECIFIC"
    , "line": "p2:L20"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw":  "화재 및 폭발위험",
      "reason":     "코드없음",
      "statements": [
        {
          "key": "화재 및 폭발위험"
        , "value": "용기가 열에 노출되면 파열되거나 폭발할 수도 있음."
        , "line": "p2:L21"
        }
      , {
          "value": "화재 위험은 무시할 수 있음."
        , "line": "p2:L22"
        }
      ]
    , "suggested_code": "S5_SPECIFIC"
    , "line": "p2:L21"
    },
    {
      "after_item": "S5_FIREFIGHT",
      "title_raw":  "화재진압시 착용할 보호구 및 예방조치",
      "reason":     "코드없음",
      "statements": [
        {
          "value": "위험없이 할 수 있으면 용기를 화재지역으로부터 이동시킬 것"
        , "line": "p2:L23"
        }
      , {
          "value": "진화가 된 후에도 상당 시간 동안 물분무기로 용기를 냉각시킬 것"
        , "line": "p2:L23"
        }
      , {
          "value": "탱크의 양 끝에는 접근하지 말 것"
        , "line": "p2:L23"
        }
      , {
          "value": "화재로 인하여 안전장치가 작동하는 소리가 나거나 탱크가 변색되는 경우에는 즉 시 대피할 것"
        , "line": "p2:L23"
        }
      , {
          "key": "탱크,철도 차량 또는 탱크 트럭의 경우:대피반경"
        , "value": "0.8km(1/2마일)"
        , "line": "p2:L23"
        }
      ]
    , "suggested_code": "S5_FIREFIGHT"
    , "line": "p2:L23"
    }
  ]
}

